using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerResourceType]
public class ConfigResourceProvider
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        Description = "Returns application configuration data")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxConnections = 100,
            Features = new { EnableCaching = true, EnableLogging = true }
        };

        return System.Text.Json.JsonSerializer.Serialize(config,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/status", Name = "Server Status",
        Description = "Returns current server status")]
    public static string GetServerStatus()
    {
        return System.Text.Json.JsonSerializer.Serialize(new
        {
            Status = "Healthy",
            Uptime = Environment.TickCount64 / 1000,
            Timestamp = DateTime.UtcNow
        }, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTools
{
    [McpServerTool, Description("Greets a user by name")]
    public static string Greet(string name) =>
        $"Hello, {name}! Welcome to the MCP HTTP server.";

    [McpServerTool, Description("Adds two numbers together")]
    public static double Add(double a, double b) => a + b;
}

